-- Dan–menyingkirkan dari–semua kota-kota Yehuda (objek) bukit-bukit–pengorbanan dan pilar-pilar–matahari dan–tenanglah kerajaan–itu di–hadapannya
BEGIN;
-- 1401400501: וַיָּ֙סַר֙ (H5493) → "Dan–menyingkirkan" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'ind'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '1401400501' AND p.language_id = (SELECT id FROM language WHERE code = 'ind') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '1401400501' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
